+fn mv(kind: MoveKind, p: [f64; 3], feed: Option<f64>, abc: Option<[f64; 3]>) -> cnc::Record {
+    cnc::Record::Move(cnc::MoveRec {
+        kind,
+        x: p[0],
+        y: p[1],
+        z: p[2],
+        feed,
+        center: None,
+        ccw: false,
+        plane: Default::default(),
+        abc,
+    })
+}
